"use client";

import React, { useState, useRef, useEffect } from "react";
import { usePathname } from "next/navigation";
import { motion } from "framer-motion";
import TrashCan from "@/public/trash_can.png";
import Image from "next/image";

interface StickerData {
  id: string;
  src: string;
  x: number;
  y: number;
}

const COLOR_SWATCHES = [
  "#FFFFFF", "#000000", "#EF4444", "#3B82F6", "#10B981", "#F59E0B", "#8B5CF6", 
];

const STORAGE_KEY = "route_stickers_map";

const DEFAULT_STICKERS: Record<string, StickerData[]> = {
  "/": [
  {
    "id": "1788009049983",
    "src": "data:image/png;base64,",
    "x": 356.3999938964844,
    "y": 99.89999389648438
  },
  {
    "id": "1788009066382",
    "src": "data:image/png;base64,",
    "x": 475.60003662109375,
    "y": 84.70001220703125
  },
  {
    "id": "1788009102827",
    "src": "data:image/png;base64,",
    "x": 606.7999877929688,
    "y": 99.10008239746094
  },
  {
    "id": "1788009148859",
    "src": "data:image/png;base64,",
    "x": 489.2001037597656,
    "y": 539.0999450683594
  },
  {
    "id": "1788009170360",
    "src": "data:image/png;base64,",
    "x": 571.5998840332031,
    "y": 503.89988708496094
  },
  {
    "id": "1788009189559",
    "src": "data:image/png;base64,",
    "x": 607.6001586914062,
    "y": 539.8999938964844
  },
  {
    "id": "1788091831805",
    "src": "data:image/png;base64,",
    "x": 952.3999633789062,
    "y": 107.09999084472656
  },
  {
    "id": "1788091890275",
    "src": "data:image/png;base64,",
    "x": 1254.800048828125,
    "y": 309.4999694824219
  }
  ],
  "/about/me":[
  ],
};

export default function StickerContainer({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const [isOpen, setIsOpen] = useState(false);
  const [stickersByRoute, setStickersByRoute] = useState<Record<string, StickerData[]>>({});
  const [isHydrated, setIsHydrated] = useState(false);
  const [isDrawing, setIsDrawing] = useState(false);
  
  const [color, setColor] = useState("#FFFFFF");
  const [tool, setTool] = useState<"brush" | "fill">("brush");
  const [brushSize, setBrushSize] = useState(4);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const trashRef = useRef<HTMLDivElement | null>(null);

  // Load saved local storage and merge with DEFAULT_STICKERS fallback
  useEffect(() => {
    const saved = sessionStorage.getItem(STORAGE_KEY);
    let savedData: Record<string, StickerData[]> = {};

    if (saved) {
      try {
        savedData = JSON.parse(saved);
      } catch (err) {
        console.error("Failed to parse saved stickers", err);
      }
    }

    const mergedStickers: Record<string, StickerData[]> = {
      ...DEFAULT_STICKERS,
      ...savedData,
    };

    setStickersByRoute(mergedStickers);
    setIsHydrated(true);
  }, []);

  // Sync state dictionary to sessionStorage
  useEffect(() => {
    if (isHydrated) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(stickersByRoute));
    }
  }, [stickersByRoute, isHydrated]);

  // Current active stickers rendered for active path
  const currentStickers = stickersByRoute[pathname] || DEFAULT_STICKERS[pathname] || [];

  const handleDeleteSticker = (id: string) => {
    setStickersByRoute((prev) => ({
      ...prev,
      [pathname]: currentStickers.filter((s) => s.id !== id),
    }));
  };

  const handleUpdatePosition = (id: string, x: number, y: number) => {
    setStickersByRoute((prev) => ({
      ...prev,
      [pathname]: currentStickers.map((s) =>
        s.id === id ? { ...s, x, y } : s
      ),
    }));
  };

  useEffect(() => {
    if (isOpen) clearCanvas();
  }, [isOpen]);

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };

  const hexToRgba = (hex: string) => {
    let c = hex.replace("#", "");
    if (c.length === 3) c = c.split("").map((x) => x + x).join("");
    const num = parseInt(c, 16);
    return [(num >> 16) & 255, (num >> 8) & 255, num & 255, 255];
  };

  const handleFloodFill = (startX: number, startY: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    const [fillR, fillG, fillB, fillA] = hexToRgba(color);
    const startIdx = (startY * width + startX) * 4;

    const startR = data[startIdx];
    const startG = data[startIdx + 1];
    const startB = data[startIdx + 2];
    const startA = data[startIdx + 3];

    if (startR === fillR && startG === fillG && startB === fillB && startA === fillA) return;

    const queue: [number, number][] = [[startX, startY]];
    const visited = new Uint8Array(width * height);

    while (queue.length > 0) {
      const [x, y] = queue.pop()!;
      const pos = y * width + x;
      const idx = pos * 4;

      if (x < 0 || x >= width || y < 0 || y >= height) continue;
      if (visited[pos]) continue;
      visited[pos] = 1;

      if (
        data[idx] === startR &&
        data[idx + 1] === startG &&
        data[idx + 2] === startB &&
        data[idx + 3] === startA
      ) {
        data[idx] = fillR;
        data[idx + 1] = fillG;
        data[idx + 2] = fillB;
        data[idx + 3] = fillA;

        queue.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]);
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const handleCanvasMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor(e.clientX - rect.left);
    const y = Math.floor(e.clientY - rect.top);

    if (tool === "fill") {
      handleFloodFill(x, y);
    } else {
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.beginPath();
      ctx.moveTo(x, y);
      setIsDrawing(true);
    }
  };

  const draw = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!isDrawing || tool !== "brush") return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
    ctx.strokeStyle = color;
    ctx.lineWidth = brushSize;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.stroke();
  };

  const stopDrawing = () => {
    setIsDrawing(false);
  };

  const handleSubmitSticker = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const imageSrc = canvas.toDataURL("image/png");

    const newSticker: StickerData = {
      id: Date.now().toString(),
      src: imageSrc,
      x: window.innerWidth / 6 - 50,
      y: window.innerHeight / 2 - 50,
    };

    setStickersByRoute((prev) => ({
      ...prev,
      [pathname]: [...currentStickers, newSticker],
    }));
    setIsOpen(false);
  };

  // Copies the active path's stickers JSON so you can paste it into DEFAULT_STICKERS
  const handleExportDefaults = () => {
    const jsonStr = JSON.stringify(currentStickers, null, 2);
    navigator.clipboard.writeText(jsonStr);
    alert(`Copied stickers array for "${pathname}" to clipboard!`);
  };

  return (
    <div className="relative min-h-full w-full overflow-hidden">
      {children}

      <div className="fixed inset-0 pointer-events-none z-40">
        {currentStickers.map((sticker) => (
          <DraggableSticker 
            key={sticker.id} 
            sticker={sticker} 
            trashRef={trashRef}
            onDelete={handleDeleteSticker}
            onUpdatePosition={handleUpdatePosition}
          />
        ))}
      </div>
      
      <div ref={trashRef} className="fixed right-5 bottom-5">
        <Image src={TrashCan} alt="trashcan" width={100} />
      </div>

      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed right-0 top-3/8 -translate-y-1/2 z-50 pointer-events-auto bg-[#3B3026] hover:bg-[#1B1714] px-2 py-4 rounded-l-xl shadow-xl transition-transform duration-300 border-l border-t border-b border-[#3B3026] flex items-center justify-center ${
          isOpen ? "-translate-x-80" : "translate-x-0"
        }`}
      >
        <span className="writing-mode-vertical text-xs tracking-widest uppercase font-semibold">
          {isOpen ? "Close" : "Stickers"}
        </span>
      </button>

      <div
        className={`rounded-bl-2xl rounded-tl-2xl fixed top-[2.5vh] right-0 h-fit w-80 bg-[#1B1714] border-l border-zinc-800 backdrop-blur-md z-50 shadow-2xl transition-transform duration-300 ease-in-out pointer-events-auto p-4 flex flex-col justify-between overflow-y-auto ${
          isOpen ? "translate-x-0" : "translate-x-full"
        }`}
      >
        <div>
          <h2 className="text-xl font-bold mb-1">Create a Sticker</h2>
          <p className="text-xs mb-3">Draw or fill color, then submit to place on screen.</p>

          <div className="space-y-3 mb-3">
            <div className="flex gap-2 bg-[#2C251E] p-1 rounded-lg">
              <button
                onClick={() => setTool("brush")}
                className={`flex-1 py-1 text-xs font-semibold rounded-md transition ${
                  tool === "brush" ? "bg-[#5A4533] -translate-y-px shadow-2xl text-[#E2CBC2]" : "text-[#6B563D] hover:-translate-y-0.5 hover:shadow-2xl hover:bg-[#5A4533] hover:text-[#E2CBC2]"
                }`}
              >
                Brush
              </button>
              <button
                onClick={() => setTool("fill")}
                className={`flex-1 py-1 text-xs font-semibold rounded-md transition ${
                  tool === "fill" ? "bg-[#5A4533] -translate-y-px shadow-2xl text-[#E2CBC2]" : "text-[#6B563D] hover:-translate-y-0.5 hover:shadow-2xl hover:bg-[#5A4533] hover:text-[#E2CBC2]"
                }`}
              >
                Bucket Fill
              </button>
            </div>

            {tool === "brush" && (
              <div className="flex items-center justify-between text-xs">
                <span>Size:</span>
                <input
                  type="range"
                  min="1"
                  max="20"
                  value={brushSize}
                  onChange={(e) => setBrushSize(Number(e.target.value))}
                  className="w-3/4 accent-primary1 cursor-pointer"
                />
              </div>
            )}

            <div className="flex items-center gap-1.5 flex-wrap">
              {COLOR_SWATCHES.map((swatch) => (
                <button
                  key={swatch}
                  onClick={() => setColor(swatch)}
                  style={{ backgroundColor: swatch }}
                  className={`w-6 h-6 rounded-full border border-zinc-600 transition-transform ${
                    color === swatch ? "scale-125 border-white ring-1 ring-offset-amber-50" : "hover:scale-110"
                  }`}
                  aria-label={`Select color ${swatch}`}
                />
              ))}

              <label className="relative w-6 h-6 rounded-full overflow-hidden border border-zinc-600 cursor-pointer hover:scale-110 transition-transform">
                <input
                  type="color"
                  value={color}
                  onChange={(e) => setColor(e.target.value)}
                  className="absolute -top-2 -left-2 w-10 h-10 cursor-pointer"
                />
              </label>
            </div>
          </div>

          <div 
            className="rounded-lg overflow-hidden border border-zinc-700 shadow-inner"
            style={{
              backgroundImage: `conic-gradient(
                #96765E 90deg, 
                #C6A991 90deg 180deg, 
                #96765E 180deg 270deg, 
                #C6A991 270deg
              )`,
              backgroundSize: "32px 32px",
            }}
          >
            <canvas
              ref={canvasRef}
              width={280}
              height={280}
              onMouseDown={handleCanvasMouseDown}
              onMouseMove={draw}
              onMouseUp={stopDrawing}
              onMouseLeave={stopDrawing}
              className={`w-full h-auto touch-none ${
                tool === "fill" ? "cursor-fill" : "cursor-crosshair"
              }`}
            />
          </div>
        </div>

        <div className="flex flex-col gap-2 mt-4">
          <div className="flex gap-2">
            <button
              onClick={clearCanvas}
              className="flex-1 px-4 py-2 bg-[#2E261F] border border-primary2 hover:bg-[#342520] text-sm font-medium rounded-md transition"
            >
              Clear
            </button>
            <button
              onClick={handleSubmitSticker}
              className="flex-1 px-4 py-2 bg-[#2E261F] border border-primary3 hover:bg-[#262e2e] text-sm font-medium rounded-md transition"
            >
              Add Sticker
            </button>
          </div>

          {/* Dev helper button to copy JSON for DEFAULT_STICKERS */}
          <button
            onClick={handleExportDefaults}
            className="w-full py-1.5 bg-[#2C251E] hover:bg-[#3B3026] text-amber-200/80 border border-amber-800/40 text-xs font-mono rounded-md transition"
          >
            Copy Route JSON for Defaults
          </button>
        </div>
      </div>
    </div>
  );
}

interface DraggableStickerProps {
  sticker: StickerData;
  trashRef: React.RefObject<HTMLDivElement | null>;
  onDelete: (id: string) => void;
  onUpdatePosition: (id: string, x: number, y: number) => void;
}

export function DraggableSticker({ sticker, trashRef, onDelete, onUpdatePosition }: DraggableStickerProps) {
  const [pos, setPos] = useState({ x: sticker.x, y: sticker.y });
  const [isDragging, setIsDragging] = useState(false);
  const [isOverTrash, setIsOverTrash] = useState(false);

  const dragOffset = useRef({ x: 0, y: 0 });
  const stickerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    setPos({ x: sticker.x, y: sticker.y });
  }, [sticker.x, sticker.y]);

  const checkIsOverTrash = () => {
    if (!stickerRef.current || !trashRef.current) return false;

    const stickerRect = stickerRef.current.getBoundingClientRect();
    const trashRect = trashRef.current.getBoundingClientRect();

    return !(
      stickerRect.right < trashRect.left ||
      stickerRect.left > trashRect.right ||
      stickerRect.bottom < trashRect.top ||
      stickerRect.top > trashRect.bottom
    );
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    setIsDragging(true);
    dragOffset.current = {
      x: e.clientX - pos.x,
      y: e.clientY - pos.y,
    };
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!isDragging) return;

    setPos({
      x: e.clientX - dragOffset.current.x,
      y: e.clientY - dragOffset.current.y,
    });

    setIsOverTrash(checkIsOverTrash());
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    setIsDragging(false);
    (e.target as HTMLElement).releasePointerCapture(e.pointerId);

    if (checkIsOverTrash()) {
      onDelete(sticker.id);
    } else {
      onUpdatePosition(sticker.id, pos.x, pos.y);
    }

    setIsOverTrash(false);
  };

  return (
    <motion.div
      ref={stickerRef}
      key={sticker.id}
      initial={{ opacity: 0, scale: 0 }}
      animate={{
        opacity: 1,
        scale: isOverTrash ? 1.25 : 1,
      }}
      transition={{ duration: 0.15, ease: "easeOut" }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      style={{ left: `${pos.x}px`, top: `${pos.y}px` }}
      className="absolute pointer-events-auto touch-none cursor-grab active:cursor-grabbing select-none z-50"
    >
      <div className="relative w-48 h-48">
        <img
          src={sticker.src}
          alt="User sticker"
          className="w-full h-full object-contain drop-shadow-lg pointer-events-none"
        />

        {isOverTrash && (
          <div className="absolute inset-0 bg-red-500/40 pointer-events-none border-2 border-primary2 mix-blend-multiply transition-opacity duration-150" />
        )}
      </div>
    </motion.div>
  );
}